fn inl_getPort_unfused<'a>(ctx: &'a Ctx, player: PlayerInitData<'a>, i: i32) -> i32 {
    let mut player = player;
    let mut i = i;
    let mut slot: i32 = ((player).slot() as i32);
    if slot == 0_i32 {
        return i;
    } else {
        return slot.wrapping_sub(1_i32);
    }
    #[allow(unreachable_code)]
    return 0;
}

